export type SkechPluginPdas = {
  game: typeof findGamePda;
  player: typeof findPlayerPda;
  pool: typeof findPoolPda;
  rewards: typeof findRewardsPda;
  callerPlayer: typeof findCallerPlayerPda;
};

export type SkechPluginRequirements = ClientWithRpc<
  GetAccountInfoApi & GetMultipleAccountsApi
> &
  ClientWithPayer &
  ClientWithTransactionPlanning &
  ClientWithTransactionSending;

export function skechProgram() {
  return <T extends SkechPluginRequirements>(
    client: T,
  ): ExtendedClient<T, { skech: SkechPlugin }> => {
    return extendClient(client, {
      skech: <SkechPlugin>{
        accounts: {
          bars: addSelfFetchFunctions(client, getBarsCodec()),
          game: addSelfFetchFunctions(client, getGameCodec()),
          holder: addSelfFetchFunctions(client, getHolderCodec()),
          market: addSelfFetchFunctions(client, getMarketCodec()),
          player: addSelfFetchFunctions(client, getPlayerCodec()),
          pool: addSelfFetchFunctions(client, getPoolCodec()),
          rewards: addSelfFetchFunctions(client, getRewardsCodec()),
        },
        instructions: {
          acceptAdmin: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getAcceptAdminInstructionAsync(input),
            ),
          claim: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getClaimInstructionAsync(input),
            ),
          collectFees: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCollectFeesInstructionAsync(input),
            ),
          deposit: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getDepositInstructionAsync({
                ...input,
                payer: input.payer ?? client.payer,
              }),
            ),
          expire: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getExpireInstructionAsync({
                ...input,
                payer: input.payer ?? client.payer,
              }),
            ),
          initMarket: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getInitMarketInstructionAsync(input),
            ),
          initRewards: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getInitRewardsInstructionAsync(input),
            ),
          initialize: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getInitializeInstructionAsync(input),
            ),
          place: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getPlaceInstructionAsync({
                ...input,
                payer: input.payer ?? client.payer,
              }),
            ),
          postBar: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getPostBarInstructionAsync(input),
            ),
          postBarAndSettle: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getPostBarAndSettleInstructionAsync({
                ...input,
                payer: input.payer ?? client.payer,
              }),
            ),
          proposeAdmin: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getProposeAdminInstructionAsync(input),
            ),
          redeem: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getRedeemInstructionAsync(input),
            ),
          redeemHouse: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getRedeemHouseInstructionAsync(input),
            ),
          revokeSession: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getRevokeSessionInstructionAsync(input),
            ),
          setConfig: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSetConfigInstructionAsync(input),
            ),
          setIouRate: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSetIouRateInstructionAsync(input),
            ),
          setMarket: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSetMarketInstructionAsync(input),
            ),
          setOracle: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSetOracleInstructionAsync(input),
            ),
          setPaused: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSetPausedInstructionAsync(input),
            ),
          setRewardsConfig: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSetRewardsConfigInstructionAsync(input),
            ),
          setSession: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSetSessionInstructionAsync({
                ...input,
                payer: input.payer ?? client.payer,
              }),
            ),
          setTreasury: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSetTreasuryInstructionAsync(input),
            ),
          settle: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSettleInstructionAsync({
                ...input,
                payer: input.payer ?? client.payer,
              }),
            ),
          shareSurplus: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getShareSurplusInstructionAsync(input),
            ),
          sweep: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSweepInstructionAsync(input),
            ),
          withdraw: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getWithdrawInstructionAsync(input),
            ),
        },
        pdas: {
          game: findGamePda,
          player: findPlayerPda,
          pool: findPoolPda,
          rewards: findRewardsPda,
          callerPlayer: findCallerPlayerPda,
        },
        identifyAccount: identifySkechAccount,
        identifyInstruction: identifySkechInstruction,
        parseInstruction: parseSkechInstruction,
      },
    });
  };
}

type MakeOptional<T, K extends keyof T> = Omit<T, K> & Partial<Pick<T, K>>;
